# Durable interpretation review is separate from report approval.
obj('InputReviewFile',{'file_id':ID,'name':TEXT,'run_id':nullable(ID),'source_kinds':arr(TEXT),'valid_rows':{'type':'integer','minimum':0},'rejected_rows':{'type':'integer','minimum':0},'excluded_rows':{'type':'integer','minimum':0},'sheets':arr(TEXT)})
obj('InputReviewAccount',{'file_id':ID,'sheet_name':TEXT,'account_code':TEXT,'account_name':TEXT,'role':nullable(TEXT)})
obj('InputReviewOverview',{'files':arr(ref('InputReviewFile')),'accounts':arr(ref('InputReviewAccount')),'source_kinds':arr(TEXT),'period_id':nullable(ID),'as_of_date':nullable(DATE),'coverage':nullable(TEXT)})
obj('InputReviewComment',{'id':ID,'body':TEXT,'file_id':nullable(ID),'sheet_name':nullable(TEXT),'account_code':nullable(TEXT),'status':enum('open','resolved'),'resolution':nullable(TEXT),'created_at':TIME})
obj('InputReviewCorrection',{'id':ID,'comment_id':ID,'snapshot_hash':HASH,'status':enum('pending','proposed','ambiguous','unavailable','usage_unknown','accepted','rejected','stale'),'content':nullable({'type':'object','additionalProperties':True}),'created_at':TIME})
obj('InputReview',{'session_id':ID,'session_version':VERSION,'required':BOOL,'ready':BOOL,'confirmed':BOOL,'snapshot_hash':HASH,'overview':ref('InputReviewOverview'),'comments':arr(ref('InputReviewComment')),'proposals':arr(ref('InputReviewCorrection')),'can_confirm':BOOL})
obj('InputReviewCommentRequest',{'snapshot_hash':HASH,'body':TEXT,'file_id':nullable(ID),'sheet_name':nullable(TEXT),'account_code':nullable(TEXT)})
obj('InputReviewProposalRequest',{'comment_id':ID,'snapshot_hash':HASH})
obj('InputReviewResolveRequest',{'reason':TEXT})
obj('InputReviewDecisionRequest',{'accept':BOOL,'reason':TEXT})
obj('InputReviewConfirmRequest',{'snapshot_hash':HASH})
R=C+'/processing-sessions/{session_id}/input-review'
endpoint('get',R,'getInputReview','InputReview',permission='company.operate')
endpoint('post',R+'/comments','createInputReviewComment','InputReview','InputReviewCommentRequest',permission='company.operate',versioned=True,status='200')
endpoint('post',R+'/comments/{comment_id}/resolve','resolveInputReviewComment','InputReview','InputReviewResolveRequest',permission='company.operate',versioned=True,status='200')
endpoint('post',R+'/proposals','proposeInputReviewCorrection','InputReview','InputReviewProposalRequest',permission='company.operate',versioned=True,status='200')
endpoint('post',R+'/proposals/{proposal_id}/decision','decideInputReviewCorrection','InputReview','InputReviewDecisionRequest',permission='company.operate',versioned=True,status='200')
endpoint('post',R+'/confirm','confirmInputReview','InputReview','InputReviewConfirmRequest',permission='company.operate',versioned=True,status='200')
SCHEMAS['ProcessingSession']['properties'].update({'input_review_required':BOOL,'input_review_confirmed':BOOL})
SCHEMAS['ProcessingSession']['required'].extend(['input_review_required','input_review_confirmed'])

SCHEMAS['AnswerConstraints']['properties']['setting_key']['enum'].append('input_review')
SCHEMAS['AnswerConstraints']['properties']['proposal_id']=ID

obj('InputReviewEntityCounts',{'parties_count':{'type':'integer','minimum':0},'invoices_count':{'type':'integer','minimum':0},'bank_accounts_count':{'type':'integer','minimum':0}})
obj('InputReviewSampleValue',{'field':TEXT,'value':nullable({'type':'string'})})
obj('InputReviewSample',{'file_id':ID,'sheet_name':TEXT,'row_number':{'type':'integer','minimum':1},'source_kind':TEXT,'state':TEXT,'error_codes':arr(TEXT),'values':arr(ref('InputReviewSampleValue'))})
SCHEMAS['InputReviewOverview']['properties'].update({'period_name':nullable(TEXT),'entities':ref('InputReviewEntityCounts'),'units':arr(TEXT),'samples':arr(ref('InputReviewSample'))})
SCHEMAS['InputReviewOverview']['required'].extend(['period_name','entities','units','samples'])

obj('InputReviewSourceControl',{'sheet_name':TEXT,'source_kind':TEXT,'key':TEXT,'outcome':enum('passed','failed','unknown')})
obj('InputReviewLedgerTotals',{'debit':nullable(string(pattern=r'^-?(?:0|[1-9][0-9]{0,39})(?:\.[0-9]{1,6})?$')),'credit':nullable(string(pattern=r'^-?(?:0|[1-9][0-9]{0,39})(?:\.[0-9]{1,6})?$')),'difference':nullable(string(pattern=r'^-?(?:0|[1-9][0-9]{0,39})(?:\.[0-9]{1,6})?$')),'rejected_rows':{'type':'integer','minimum':0},'basis':enum('readable_source_rows_not_posted')})
SCHEMAS['InputReviewFile']['properties'].update({'controls':arr(ref('InputReviewSourceControl')),'ledger_totals':nullable(ref('InputReviewLedgerTotals'))})
SCHEMAS['InputReviewFile']['required'].extend(['controls','ledger_totals'])
